// Normalises platform payloads into a common metric set.
// Metrics that the platform does not return are recorded as null, never as 0
// and never invented.
const ctx = $('CODE - Restore Context').first().json;
const raw = $input.first().json || {};
const isError = !!raw.error;

function insight(name) {
  const arr = raw?.insights?.data || [];
  const hit = arr.find(d => d.name === name);
  const v = hit?.values?.[0]?.value;
  return Number.isFinite(Number(v)) ? Number(v) : null;
}
const num = v => (Number.isFinite(Number(v)) ? Number(v) : null);

let m = { impressions: null, reach: null, reactions: null, comments: null, shares: null };

if (!isError && ctx.platform === 'facebook') {
  m = {
    impressions: insight('post_impressions'),
    reach: insight('post_impressions_unique'),
    reactions: num(raw?.reactions?.summary?.total_count),
    comments: num(raw?.comments?.summary?.total_count),
    shares: num(raw?.shares?.count)
  };
} else if (!isError && ctx.platform === 'instagram') {
  m = {
    impressions: insight('impressions'),
    reach: insight('reach'),
    reactions: num(raw?.like_count),
    comments: num(raw?.comments_count),
    shares: insight('shares')
  };
}

const available = Object.values(m).some(v => v !== null);
return [{
  json: {
    ...ctx,
    metrics: m,
    metrics_available: available,
    retrieval_error: isError ? { stage: 'analytics_retrieval', platform: ctx.platform, error_code: String(raw.error?.code || 'metrics_unavailable'), message: String(raw.error?.message || 'Metrics could not be retrieved'), retry_count: 2, timestamp: new Date().toISOString() } : null,
    raw_payload: raw,
    captured_at: new Date().toISOString()
  }
}];

/*
 * ENGAGEMENT SCORE (deterministic, documented, reproducible)
 * ---------------------------------------------------------
 * interactions = 1.0*reactions + 2.0*comments + 3.0*shares
 *   Weights reflect increasing effort/intent, not measured causal value.
 * denominator  = reach, else impressions, else null
 *
 * If a denominator exists:
 *   rate  = interactions / denominator
 *   score = min(1, rate / CEIL)   with CEIL = 0.10 (a 10% interaction rate
 *                                  maps to the top of the scale)
 * If no denominator exists the score is null. It is NEVER imputed.
 * Metrics absent from the API contribute 0 interactions but are reported
 * separately in metrics_missing so downstream agents know what was unobserved.
 */
const ctx = $input.first().json;
const m = ctx.metrics;
const CEIL = 0.10;
const W = { reactions: 1.0, comments: 2.0, shares: 3.0 };

const missing = Object.entries(m).filter(([, v]) => v === null).map(([k]) => k);
const interactions = (m.reactions || 0) * W.reactions + (m.comments || 0) * W.comments + (m.shares || 0) * W.shares;
const denom = m.reach ?? m.impressions ?? null;

let rate = null, score = null;
if (denom && denom > 0) {
  rate = interactions / denom;
  score = Number(Math.min(1, rate / CEIL).toFixed(6));
}

return [{
  json: {
    ...ctx,
    engagement: {
      weighted_interactions: Number(interactions.toFixed(4)),
      denominator_metric: m.reach != null ? 'reach' : (m.impressions != null ? 'impressions' : null),
      denominator_value: denom,
      interaction_rate: rate === null ? null : Number(rate.toFixed(6)),
      engagement_score: score,
      weights: W,
      normalisation_ceiling: CEIL,
      metrics_missing: missing,
      formula: 'score = min(1, (1*reactions + 2*comments + 3*shares) / denominator / 0.10)',
      note: 'Descriptive score over observed metrics. No causal interpretation.'
    }
  }
}];

const ctx = $('CODE - Calculate Engagement Score').first().json;
const b = $input.first().json || {};
const n = Number(b.n) || 0;
return [{
  json: {
    ...ctx,
    baseline: {
      observations: n,
      available: n >= 3,
      client_average_engagement_score: b.client_avg_score != null ? Number(Number(b.client_avg_score).toFixed(4)) : null,
      client_average_impressions: b.client_avg_impressions != null ? Math.round(Number(b.client_avg_impressions)) : null,
      client_average_reach: b.client_avg_reach != null ? Math.round(Number(b.client_avg_reach)) : null,
      platform_average_engagement_score: b.platform_avg_score != null ? Number(Number(b.platform_avg_score).toFixed(4)) : null,
      platform_observations: Number(b.platform_n) || 0
    }
  }
}];

const ctx = $('CODE - Build Analytics Context').first().json;
const engRaw = $('AI - Engagement Agent').first().json;
const anaRaw = $input.first().json;

function parse(r) {
  try { return JSON.parse(String(r?.choices?.[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { return null; }
}
const engagementAgent = parse(engRaw);
const analyticsAgent = parse(anaRaw);
const errors = [];

const arr = (o, k) => Array.isArray(o?.[k]);
if (!engagementAgent) errors.push('engagement_agent_unparseable');
else {
  if (typeof engagementAgent.summary !== 'string') errors.push('engagement_summary_invalid');
  const ps = Number(engagementAgent.performance_score);
  if (!Number.isFinite(ps) || ps < 0 || ps > 1) errors.push('performance_score_invalid');
  for (const k of ['strengths', 'weaknesses', 'recommendations']) if (!arr(engagementAgent, k)) errors.push('engagement_' + k + '_invalid');
}
if (!analyticsAgent) errors.push('analytics_agent_unparseable');
else {
  if (typeof analyticsAgent.performance_interpretation !== 'string') errors.push('interpretation_invalid');
  for (const k of ['successful_themes', 'weak_themes', 'platform_insights', 'timing_observations', 'recommendations_for_future_campaigns']) if (!arr(analyticsAgent, k)) errors.push('analytics_' + k + '_invalid');
}

// The numeric engagement score is ALWAYS the deterministic one, never the LLM's.
return [{
  json: {
    ...ctx,
    insights: {
      engagement_agent: engagementAgent,
      analytics_agent: analyticsAgent,
      validation_errors: errors,
      valid: errors.length === 0,
      model_version: $env.OPENAI_MODEL || 'gpt-4.1'
    }
  }
}];

const ctx = $('CODE - Validate Analytics Output').first().json;
const row = $input.first().json || {};
return [{ json: { campaign_id: ctx.campaign_id, publication_id: ctx.publication_id, platform: ctx.platform, campaign_status: row.status || null, engagement_score: ctx.engagement.engagement_score, metrics_available: ctx.metrics_available, insights_valid: ctx.insights.valid, validation_errors: ctx.insights.validation_errors } }];
